    public static final int CONSTRUCTORS_INDEX = 1;
    public static final int METHOD_INDEX = 2;
}

class AnotherMembersClass {
    public static final int CONSTRUCTORS_INDEX = 99; // A constant in a different class
}

class TestOtherUsages {
    public int getOtherConstant() {
        // This should not be matched as it's a different class constant
        return test.AnotherMembersClass.CONSTRUCTORS_INDEX;
    }

    public int getDifferentMember() {
        // This should not be matched as it's a different constant from the same old class
        return test.MembersOrderPreferenceCache.METHOD_INDEX;
